488:     void doTest_comparisons_UtcInstant(UtcInstant... instants) {
489:         for (int i = 0; i < instants.length; i++) {
490:             UtcInstant a = instants[i];
491:             for (int j = 0; j < instants.length; j++) {
492:                 UtcInstant b = instants[j];
493:                 if (i < j) {
494:                     assertEquals(-1, a.compareTo(b));
495:                     assertNotEquals(a, b);
496:                     assertTrue(a.isBefore(b));
497:                     assertFalse(a.isAfter(b));
498:                 } else if (i > j) {
499:                     assertEquals(1, a.compareTo(b));
500:                     assertNotEquals(a, b);
501:                     assertFalse(a.isBefore(b));
502:                     assertTrue(a.isAfter(b));
503:                 } else {
504:                     assertEquals(0, a.compareTo(b));
505:                     assertEquals(a, b);
506:                     assertFalse(a.isBefore(b));
507:                     assertFalse(a.isAfter(b));
508:                 }
509:             }
510:         }
511:     }
